# World Master Map
# This file includes all regions of the world
# Format: include filename.map offsetX offsetZ
# lumbridge.map, alkharid.map and varrock.map are generated at 2 m per OSRS tile (scripts/osrs_map)
# in one shared frame (offset 0 0); the other regions sit at their OSRS directions, clear of them.

# Lumbridge - starting area (centered at origin)
include lumbridge.map 0 0

# Varrock - northern city (shares Lumbridge's frame)
include varrock.map 0 0

# Falador - western city with White Knights' Castle
include falador_cv.map -380 -230

# Al Kharid - desert region to the east (shares Lumbridge's frame)
include alkharid.map 0 0

# Wilderness - dangerous northern region (level 3-48 enemies); its south edge (local z 300) is just
# north of Varrock at OSRS y 3520
include wilderness.map 0 -905
